/**
 * Edge-safe config shared with middleware. Kept free of Node-only code
 * (bcrypt, the users store) so it can run in the Edge runtime; the real
 * providers are added on top of this in `src/auth.ts`.
 */
export const authConfig = {
  pages: {
    signIn: "/signin",
  },
  callbacks: {
    authorized({ auth, request: { nextUrl } }) {
      const isLoggedIn = !!auth?.user;
      const isOnDashboard = nextUrl.pathname.startsWith("/dashboard");
      if (isOnDashboard) return isLoggedIn;
      return true;
    },
  },
  providers: [],
} satisfies NextAuthConfig;

